    # Determine if second level key is dynamically constructed via Fn::Sub
    # using pseudo parameters like AWS::AccountId or AWS::Region. If so,
    # we will not strictly validate against existing keys as the value
    # depends on the execution context.
    def _is_dynamic_second_level_with_pseudo(inst: Any) -> bool:
        k, v = is_function(inst)
        if k == "Fn::Sub":
            # String form
            if isinstance(v, str):
                return ("${AWS::AccountId}" in v) or ("${AWS::Region}" in v)
            # Array form [ string, parameters ]
            if isinstance(v, list) and len(v) == 2:
                s, params = v
                if isinstance(s, str) and (
                    "${AWS::AccountId}" in s or "${AWS::Region}" in s
                ):
                    return True
                if isinstance(params, dict):
                    for pv in params.values():
                        pk, pv_val = is_function(pv)
                        if pk == "Ref" and pv_val in ("AWS::AccountId", "AWS::Region"):
                            return True
        return False

    dynamic_second_level = _is_dynamic_second_level_with_pseudo(instance[2])

